function ActionEntryMap:Awake()
    self.animator = KTool.GetComponent(self.Camera.gameObject, typeof(Animator))
    self.animator.keepAnimatorControllerStateOnDisable = true

    self.activeImage = self.ActivityGroup1.transform:Find("AnimRoot/ImgBgTexture")
    self.txtName = self.ActivityGroup1.transform:Find("AnimRoot/Information/TxtName")
    self.txtTime = self.ActivityGroup1.transform:Find("AnimRoot/Information/TxtTime")
    self.goGroup = self.ActivityGroup1.transform:Find("AnimRoot/Information/GoGroup")
    KTool.SetActive(self.goGroup, false)
    if self.txtTime then
        CfUtils.FillText(self.txtTime, "")
    end
    SetButtonAction(self.ActivityGroup1.gameObject, function()
        GameUtils.Toast(localize('暂无活动'))
    end)

end

function ActionEntryMap:PlayCamInAni()
    local id = KCookie.Get("ActionEntryMapId")
    KCookie.Set("ActionEntryMapId", 0)
    if checkNumber(id) > 0 then
        cs_coroutine.start(function()
            self._isPlayAni = true
            coroutine.yield(self:PlayCamAni(id, true))
            self._isPlayAni = false
        end)
    else
        CfUtils.PlayAnimator(self.Camera, "Open")
    end
end

function ActionEntryMap:DeleteAnimator()
    ---@type UnityEngine.Animator
    local animator = KTool.GetComponent(URPCameraController.Instance.gameObject, typeof(Animator))
    if not isNull(animator) then
        KTool.SafeDelete(animator, true)
    end

    self:SetDailyQuestState(false)
end

function ActionEntryMap:RuntimeAnimator()
    ---@type UnityEngine.Animator
    local animator = KTool.GetOrAddComponent(URPCameraController.Instance.gameObject, typeof(Animator))
    ---@type UnityEngine.Animator
    local t = self.animator
    animator.runtimeAnimatorController = t.runtimeAnimatorController
    animator.keepAnimatorControllerStateOnDisable = true
end

function ActionEntryMap:PlayCamOpenAni()
    local state = KCookie.Get(Constants.UICacheDataKeys.ACTION_ENTRY_STATE)
    if not string.isEmpty(state) then
        ---@type UnityEngine.Animator
        local animator = KTool.GetOrAddComponent(URPCameraController.Instance.gameObject, typeof(Animator))
        animator.keepAnimatorControllerStateOnDisable = true
        self._isPlayAni = true
        cs_coroutine.start(function()
            local Camera = CS.UnityEngine.Camera
            local URPCamera = URPCameraController.Instance.gameObject:GetComponent(typeof(Camera))
            URPCamera.focalLength = 49.45459
            
            ---设置为2的状态
            animator:SetInteger(state, 2)
            --coroutine.yield(WaitForSeconds(0.667))
            self._isPlayAni = false
            KCookie.RemoveAllListener(Constants.UICacheDataKeys.ACTION_ENTRY_STATE)
            --animator:SetInteger(CAMERA_ACTION_NAMES.LEFT, 0)
            --animator:SetInteger(CAMERA_ACTION_NAMES.TOP, 0)
            --animator:SetInteger(CAMERA_ACTION_NAMES.BOTTOM, 0)
        end)
    else
        cs_coroutine.start(function()
            self._isPlayAni = true
            CfUtils.PlayAnimator(self.Camera, "Open")
            coroutine.yield(WaitForSeconds(0.667))
            self._isPlayAni = false
        end)
    end
end

