function ActionEntryMap:FreshUI(serverData, effectGos)
    for i = 1, #CommonQuestEntryMap do
        local key = string.format('Square%d', i)
        local rootGo = self[key]
        if not isNull(rootGo) then
            KTool.SetActive(rootGo, true)
        end
    end
    ---显示boss站相关的逻辑
    KTool.SetActive(self.ItemActivity.gameObject, true)
    KTool.SetActive(self.BootAnim.gameObject, false)

    self._serverData = serverData
    self._effectGos = checkTable(effectGos)
    self:InitData()

    ---设置最下面一排按钮的事件
    self:SetBottomButtonActions()
    ---活动相关
    self:FillActivityEntryInfos()
    ---爬塔信息
    self:FillTowerInfo()
    ---高端副本
    self:FillAdvancedTraining()


    self:StartTimeDown()

    self:PlayCamInAni()

    CfUtils.SetActive(self.ActivityGroup3, false)
end

