--- FillActivityGroupAndInitDojo
---@param data table
---@param isUpdateTime boolean
function ActionEntryMap:FillActivityGroupAndInitDojo(data, isUpdateTime)
    local dojo = ActivityDojo.New()
    dojo:Fill(data)
    local curTime   = os.time()
    local startTime = curTime + dojo.startTime
    local closeTime = curTime + dojo.closeTime
    local endTime   = curTime + dojo.endTime
    if isUpdateTime then
        dojo.startTime = startTime
        dojo.closeTime = closeTime
        dojo.endTime = endTime
    end

    local transform = self.ActivityGroup1.transform
    CfUtils.FillImage(transform:Find("AnimRoot/ImgBgTexture"), checkString(ParseUtils.ParsePathNameByData(checkString(data.entranceImage))))
    CfUtils.FillText(transform:Find("AnimRoot/Information/TxtName"), data.name)
    CfUtils.FillText(transform:Find("AnimRoot/Information/TxtTime"), os.date("%Y.%m.%d", startTime).."-"..os.date("%Y.%m.%d", endTime))

    return dojo
end

--- CheckActivityIsUnlock
---@param dojo ActivityDojo
---@return boolean 是否解锁
function ActionEntryMap:CheckActivityIsUnlock(dojo)
    local unlock = checkTable(dojo.unlock)
    if next(unlock) == nil then
        return true
    end
    local vo = unlock[1]
    local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
    if not isUnlock then
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        GameUtils.Toast(err)
    end
    return isUnlock
end


--爬塔信息
function ActionEntryMap:FillAdvancedTraining()
    local id = Constants.SystemToggleIds.Id23
    local go = self.AdvancedTrainingGroup

    local lockNode = go.transform:Find("Lock")
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(id)
    KTool.SetActive(lockNode, not isUnlock)
    local NameTitle = go.transform:Find("NameTitle")
    local TxtName = NameTitle.transform:Find("TxtName")
    CfUtils.SetUISwitchImage(NameTitle, isUnlock and 2 or 1)
    CfUtils.SetUISwitchText(TxtName, isUnlock and 2 or 1)
    SetButtonAction(go, function()
        self:OnClickQuestEntry(id)
    end)

end

--爬塔信息
function ActionEntryMap:FillTowerInfo()
    local id = Constants.SystemToggleIds.Id15
    local go = self.CollectGroup
    local serverData = self._serverData[checkString(id)]

    local isOpen = towerQuestComponent:IsOpen()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(id)
    local aniName = "Open"
    if isUnlock then
        aniName = "Open"
    else
        aniName = "Lock"
    end
    if QuestConfMgr:GetInstance():IsHasUnlockCookie(id) then
        aniName = "LockIdle"
    end

    CfUtils.PlayAnimator(go, aniName)
    local open1Go = go.transform:Find("Open1")
    KTool.SetActive(open1Go, isUnlock and isOpen)
    --CfUtils.FillText(open1Go.transform:Find("TxtTime"), CfUtils.GetTimeHMS4(serverData.climbingTowerRemainTime))
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", id)
    CfUtils.SetActive(open1Go.transform:Find("TxtTime"), false)

    local status = 1
    if checkNumber(serverData.status) == 1 then
        --1 进行中  2 已完成 3 未开启
        status = 1
    elseif checkNumber(serverData.status) == 2 then
        status = 2
    end
    CfUtils.SetUISwitchText(open1Go.transform:Find("TxtState"), status)
    CfUtils.SetActive(open1Go.transform:Find("TxtState"), isUnlock)

    local status = isUnlock and 2 or 1
    CfUtils.SetUISwitchImage(go.transform:Find("NameTitle"), status)
    CfUtils.SetUISwitchImage(go.transform:Find("TxtName"), status)

    local txtNumGo = go.transform:Find("Open2/TxtDepth/TxtNum")
    local imgMaxGo = go.transform:Find("Open2/ImgMax")

    local isMax = false
    local vo
    if checkNumber(serverData.playerTowerId) == 0 then
        vo = QuestConfMgr:GetInstance():GetFirstTowerQuestVo()
    else
        local nextId = QuestConfMgr:GetInstance():GetNextTowerQuestId(serverData.playerTowerId)
        --为0为关底
        if checkNumber(nextId) ~= 0 then
            vo = QuestConfMgr:GetInstance():GetQuestVoById(nextId)
        else
            isMax = true
            vo = QuestConfMgr:GetInstance():GetQuestVoById(serverData.playerTowerId)
        end
    end

    KTool.SetActive(go.transform:Find("Open2/TxtDepth"), not isMax)
    KTool.SetActive(txtNumGo, not isMax)
    KTool.SetActive(imgMaxGo, isMax)

    local t = QuestConfMgr:GetInstance():GetAllTowerQuestIds()
    local allCount = table.count(t)

    local num = table.getKey(t, checkString(vo.id))
    CfUtils.FillText(txtNumGo, num.."/"..allCount)
    CfUtils.FillText(imgMaxGo.transform:Find("TxtNum"), allCount.."/"..allCount)

    SetButtonAction(go, function()
        self:OnClickQuestEntry(id)
    end)

    KTool.SetActive(go.transform:Find("Open2"), isOpen)
    KTool.SetActive(go.transform:Find("NotOpen"), not isOpen)
end

function ActionEntryMap:InitData()
    ActivityQuestEntrys = {
        {
            go = self.ActivityGroup2,
            id = Constants.SystemToggleIds.Id14,
        },
        {
            go = self.ActivityGroup3,
            id = Constants.SystemToggleIds.Id16,
        },
        {
            go = self.ActivityGroup4,
            id = Constants.SystemToggleIds.Id8,
        },
        {
            go = self.ActivityGroup5,
            id = Constants.SystemToggleIds.Id9,
        },
    }
end

function ActionEntryMap:StartTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:UpdateActionInfo()

        --只有活动副本会有时间显示
        for k, v in pairs(ActivityQuestEntrys) do
            self:FillActivityEntryInfo(v, true)
        end
    end, CountDownTime, false, true)
end

--服务器时间倒计时跟新
function ActionEntryMap:UpdateActionInfo()
    if not self._serverData then
        return
    end
    for k, v in pairs(self._serverData) do
        if isTable(v) then
            if checkNumber(k) == Constants.SystemToggleIds.Id3 then
                if checkNumber(v.closeTime) > 0 then
                    v.closeTime = checkNumber(v.closeTime) - 1
                end
            elseif checkNumber(k) == Constants.SystemToggleIds.Id8 then
                v.remainTime = checkNumber(v.remainTime) - 1
                if v.remainTime <= 0 then
                    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", checkNumber(k))
                    if vo then
                        v.remainTime = checkNumber(vo.duration)
                    end
                end
            elseif checkNumber(k) == Constants.SystemToggleIds.Id22 then
                if checkNumber(v.closeTime) > 0 then
                    v.closeTime = checkNumber(v.closeTime) - 1
                end
            elseif checkNumber(k) == Constants.SystemToggleIds.Id20 then
                if checkNumber(v.questRemainTime) > 0 then
                    v.questRemainTime = checkNumber(v.questRemainTime) - 1
                end
            elseif checkNumber(k) == Constants.SystemToggleIds.Id16 then
                v.nextStageLeftSeconds = checkNumber(v.nextStageLeftSeconds - 1)
                if checkNumber(v.nextStageLeftSeconds) <= 0 then
                    ---@type PVPArenaComponent
                    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
                    self._serverData[k] = comp:GetPVPArenaEntryDojo()
                end
            end
        end
    end
end

function ActionEntryMap:FillActivityEntryInfos()
    for k, v in pairs(ActivityQuestEntrys) do
        self:FillActivityEntryInfo(v)

        SetButtonAction(v.go, function()
            self:OnClickQuestEntry(v.id)
        end)
    end
end

--绘制限时信息
function ActionEntryMap:FillActivityEntryInfo(data, isRefresh)
    if not data then
        return
    end
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(data.id)
    local isOpen = false

    local serverData = self._serverData[checkString(data.id)]
    local time = 0

    if checkNumber(data.id) == Constants.SystemToggleIds.Id14 then
        --世界boss
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
        
        if not isRefresh then
            local planId = checkNumber(comp:GetCurBossPlanId())
            if planId > 0 then
                local vo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(planId)
                if vo then
                    CfUtils.FillImage(data.go.transform:Find("AnimRoot/ImgIcon"), vo.actionId)
                end
            end
        end

        time = math.abs(comp:GetRemainTime())
        isOpen = comp:IsOpen()
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id16 then
        --- 风暴巅峰
        time = checkNumber(serverData.nextStageLeftSeconds)
        isOpen = (checkNumber(data.isEnd) == 0)
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id8 then
        --迷宫
        time = checkNumber(serverData.remainTime)
        isOpen = (checkNumber(serverData.remainTime) > 0)
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id9 then
        --风暴挑战
        time = checkNumber(playerComponent.playerDojo.trialRemainTime)
        isOpen = time > 0
    end
    local animRootGo = data.go.transform:Find("AnimRoot")
    if not isRefresh then
        local aniName = ""
        if isUnlock then
            aniName = "Open"
        else
            aniName = "Lock"
        end

        if QuestConfMgr:GetInstance():IsHasUnlockCookie(data.id) then
            aniName = "LockIdle"
        end
        CfUtils.PlayAnimator(animRootGo, aniName)
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", data.id)
    --CfUtils.FillText(animRootGo.transform:Find("TxtTime"), vo.timeTxt)
    CfUtils.FillText(animRootGo.transform:Find("TxtName"), vo.name)

    KTool.SetActive(animRootGo.transform:Find("NotOpen"), not isOpen)

    local isShowRedPoint = false
    local status = 1
    if checkNumber(data.id) == Constants.SystemToggleIds.Id14 then
        --世界boss
        status = 2
        if checkNumber(serverData.status) == 1 then
            --1 进行中  2 已完成 3 未开启
            status = 2
        elseif checkNumber(serverData.status) == 2 then
            status = 3
        elseif checkNumber(serverData.status) == 3 then
            status = 5
        end

        isShowRedPoint = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.WorldBoss)) > 0 
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id16 then
        --- 风暴巅峰
        status = 1
        if checkNumber(serverData.status) == 1 then
            --1 进行中  2 已完成 3 未开启
            status = 1
        elseif checkNumber(serverData.status) == 2 then
        elseif checkNumber(serverData.status) == 3 then
            status = 5
        end
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id8 then
        --迷宫
        status = 1
        if checkNumber(serverData.status) == 1 then
            --1 进行中  2 已完成 3 未开启
            status = 1
        elseif checkNumber(serverData.status) == 2 then
            status = 4
        elseif checkNumber(serverData.status) == 3 then
        end
    elseif checkNumber(data.id) == Constants.SystemToggleIds.Id9 then
        --风暴挑战
        status = 2
        if checkNumber(serverData.status) == 1 then
            --1 进行中  2 已完成 3 未开启
            status = 2
        elseif checkNumber(serverData.status) == 2 then
            status = 3
        elseif checkNumber(serverData.status) == 3 then
        end

        isShowRedPoint = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.TrailQuest)) > 0 
    end
    CfUtils.SetUISwitchText(animRootGo.transform:Find("TxtTime"), status)

    CfUtils.FillText(animRootGo.transform:Find("NotOpen/TxtState"), localize("当前暂未开启"))

    local redGo = GameUtils.GetRedPointGo(animRootGo)
    if redGo then 
        CfUtils.SetActive(redGo, isShowRedPoint)
    end
end

