--跳转过来使用
function ActionEntryMap:OnClickDailyEntryQuestEntry(id, time)
    local isUnlock, err = GameUtils.IsUnlockedBySystemTogId(id)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(id))
        return
    end
    self:EntryQuest(id, time)
end

function ActionEntryMap:OnClickQuestEntry(id, time)
    if self._isPlayAni then
        return
    end
    local isUnlock, err = GameUtils.IsUnlockedBySystemTogId(id)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(id))
        return
    end
    self:EntryQuest(id, time)
end

