function ActionEntryMap:EntryQuest(id, time)
    if checkNumber(id) == Constants.SystemToggleIds.Id4 or checkNumber(id) == Constants.SystemToggleIds.Id5 or checkNumber(id) == Constants.SystemToggleIds.Id6 then
        --日常
        local copyType = 1
        local key = string.format('Square%d', 1)
        if checkNumber(id) == Constants.SystemToggleIds.Id4 then
            copyType = 1
        elseif checkNumber(id) == Constants.SystemToggleIds.Id5 then
            copyType = 2
            key = string.format('Square%d', 2)
        elseif checkNumber(id) == Constants.SystemToggleIds.Id6 then
            copyType = 3
            key = string.format('Square%d', 4)
        end
        local go = self[key]
        local delay = 0
        if not isNull(time) then
            delay = checkNumber(time)
        end

        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.BOTTOM, delay, function()
            self:SetDailyQuestState(true)
            Events.Broadcast(Constants.EventNames.DAILY_QUEST_BUTTON_CLICK_ACTION, copyType, id, go)
        end)
    elseif checkNumber(id) == Constants.SystemToggleIds.Id10 then
        --装备
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.ACTION_ENTRY_STATE)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog, parameters = {} }, {
            { id = Constants.UITypeIds.ActionEntryDialog }
        })
        xRecord.record('3-003')
        --questType = Constants.IDType.QuestPrimaryEquipCopy
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id8 then
        --迷宫
        xRecord.record('3-005')
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            local MazeMgr = import('Game.Maze.MazeMgr')
            MazeMgr:GetInstance():EnterMaze({ { id = Constants.UITypeIds.ActionEntryDialog } })
        end)
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id14 then
        --世界boss
        xRecord.record('3-009')
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
            worldBossComponent:OnWorldBossEnter()
        end)
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id11 then
        --假想实战
        xRecord.record('3-006')
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIGachaCoinQuestDialog },
                    { { id = Constants.UITypeIds.ActionEntryDialog } }
            )
        end)
        --questType = Constants.IDType.QuestGachaCoin
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id20 then
        --定向作战
        --GameUtils.ShowBlackOverlay()
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.DirectionalDialog },
                    { { id = Constants.UITypeIds.ActionEntryDialog } }
            )
        end)
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id15 then
        --爬塔
        local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
        local isOpen = towerQuestComponent:IsOpen()
        if not isOpen then
            GameUtils.Toast(localize("未开启"))
            return
        end
        KCookie.Set("EnterUIClimbTowerMainDialog", 1)
        xRecord.record('3-008')
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.LEFT, 0, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIClimbTowerMainDialog }, { { id = Constants.UITypeIds.ActionEntryDialog } })
        end)
        KCookie.Set("ActionLastMapId", id)
    elseif checkNumber(id) == Constants.SystemToggleIds.Id23 then
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.LEFT, 0.1, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.AdvancedTrainingDialog }, { { id = Constants.UITypeIds.ActionEntryDialog } })
        end)
        KCookie.Set("ActionLastMapId", id)
    elseif checkNumber(id) == Constants.SystemToggleIds.Id9 then
        --风暴挑战
        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
        if trialRemainTime <= Constants.MIN_TRIAL_CAN_ENTER then
            GameUtils.Toast(localize('试炼未开始'))
            return
        end
        xRecord.record('3-007')
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStageMain }, { { id = Constants.UITypeIds.ActionEntryDialog } })
        end)
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id22 then
        KCookie.Set("UITalentMaterialDialogEntry", 1)
        --天赋
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.ACTION_ENTRY_STATE)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialDialog, parameters = {} }, {
            { id = Constants.UITypeIds.ActionEntryDialog }
        })
        KCookie.Set("ActionLastMapId", id)

    elseif checkNumber(id) == Constants.SystemToggleIds.Id16 then
        self:PlayCameraAnimation(CAMERA_ACTION_NAMES.TOP, 0.1, function()
            --- 风暴巅峰
            ---@type PVPArenaUtils
            local PVPArenaUtils = import('Game.Utils.PVPArenaUtils')
            local excludeDialogs = {
                { id = Constants.UITypeIds.ActionEntryDialog },
            }
            PVPArenaUtils.ShowMainDialog(excludeDialogs, true)
        end)
        KCookie.Set("ActionLastMapId", id)

    else
        GameUtils.Toast(localize("暂未开放"))
    end
    KCookie.Set("ActionEntryMapId", id)
end

function ActionEntryMap:PlayCameraAnimation(stateName, time, cb)
    --if isNull(time) then
    --    time = 0.2
    --end
    self._isPlayAni = true
    if not isNull(self.animator) then
        UIRaycastBlocker:AddCondition("PlayCameraAnimation")
        cs_coroutine.start(function()
            try(function()
                ---@type UnityEngine.Animator
                ---@type UnityEngine.Animator
                local animator = KTool.GetOrAddComponent(URPCameraController.Instance.gameObject, typeof(Animator))
                
                if stateName == CAMERA_ACTION_NAMES.BOTTOM then
                    if checkNumber(KCookie.Get("IsHomeEntry")) == 1 then
                        animator:Play("IdleB")
                    else
                        animator:SetInteger(stateName, 1)
                    end                    
                else
                    animator:SetInteger(stateName, 1)
                end

                animator.keepAnimatorControllerStateOnDisable = true

                KCookie.Set(Constants.UICacheDataKeys.ACTION_ENTRY_STATE, stateName)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(time))
                self._isPlayAni = false
                if cb then
                    cb()
                end
            end, function()
                print(debug.traceback())
                UIRaycastBlocker:RemoveCondition("PlayCameraAnimation")
            end)
            UIRaycastBlocker:RemoveCondition("PlayCameraAnimation")
        end)
    end
end

function ActionEntryMap:PlayCamAni(id, isIn)
    local name, go, time = self:GetAniName(id, isIn)
    CfUtils.PlayAnimator(self.Camera, name)
    if not isNull(go) then
        KTool.SetActive(go, true)
    end
    --coroutine.yield(WaitForSeconds(3))
    coroutine.yield(WaitForSeconds(time))
    if not isNull(go) then
        KTool.SetActive(go, false)
    end
end

function ActionEntryMap:GetAniName(id, isIn)
    if checkNumber(id) == checkNumber(Constants.SystemToggleIds.Id15) then
        return isIn and "LToCenter" or "CenterToL", self._effectGos[3], isIn and 0.667 or 1.1
    end
    for k, v in pairs(ActivityQuestEntrys) do
        if checkNumber(v.id) == checkNumber(id) then
            return isIn and "TToCenter" or "CenterToT", self._effectGos[2], isIn and 0.667 or 0.8
        end
    end
    for k, v in pairs(CommonQuestEntryMap) do
        if checkNumber(v) == checkNumber(id) then
            return isIn and "BToCenter" or "CenterToB", self._effectGos[1], isIn and 0.667 or 1.017
        end
    end
    return "Open", nil, 0.667
end

function ActionEntryMap:RemoveTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function ActionEntryMap:OnDestroy()
    --self:RemoveTimeDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ActionEntryMap